from functools import wraps
from threading import Lock


def rate_limit(leak_rate, capacity, clock):
    if leak_rate < 0:
        raise ValueError("leak_rate must be non-negative")
    if capacity < 0:
        raise ValueError("capacity must be non-negative")

    def decorator(func):
        water = 0
        last_leak = None
        lock = Lock()

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal water, last_leak

            with lock:
                now = clock()
                if last_leak is None:
                    last_leak = now
                else:
                    if now < last_leak:
                        now = last_leak
                    water = max(0, water - (now - last_leak) * leak_rate)
                    last_leak = now

                if water + 1 <= capacity:
                    water += 1
                    admitted = True
                else:
                    admitted = False

            return func(*args, **kwargs) if admitted else False

        return wrapper

    return decorator

